{
  "hooks": {
    "UserPromptSubmit": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "'<code-root>/bin/fm-busy-event.sh' apply '<fixture>/home/state' 'rl4' busy --gen 'g1791728483.2371657.30191' --source claude-hook --event user-prompt-submit 2>/dev/null || true"
          }
        ]
      }
    ],
    "Stop": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "touch '<fixture>/home/state/rl4.turn-ended'; '<code-root>/bin/fm-busy-event.sh' apply '<fixture>/home/state' 'rl4' idle --gen 'g1791728483.2371657.30191' --source claude-hook --event stop 2>/dev/null || true"
          }
        ]
      }
    ],
    "StopFailure": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "'<code-root>/bin/fm-busy-event.sh' apply '<fixture>/home/state' 'rl4' idle --gen 'g1791728483.2371657.30191' --source claude-hook --event stop-failure 2>/dev/null || true"
          }
        ]
      }
    ],
    "SessionEnd": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "'<code-root>/bin/fm-busy-event.sh' apply '<fixture>/home/state' 'rl4' idle --gen 'g1791728483.2371657.30191' --source claude-hook --event session-end 2>/dev/null || true"
          }
        ]
      }
    ]
  }
}
